// SessionStart playbook — produce a markdown brief for the agent.
// Input contract (from services/svc-ai-chat/src/routes/dirigent-supervisor.ts):
//   { event, story_id, session_id, tool_input, tool_output, user_prompt, transcript_excerpt }
// Output contract (per README-dirigent-supervisor.md):
//   { advisory: string, decision: 'allow', reason?: string }
const body = $input.first().json.body || $input.first().json;
const storyId = body.story_id || null;
const sessionId = body.session_id || null;
if (body.event !== 'session_start') {
  throw new Error(`WF_DIRIGENT_BRIEFING expects event=session_start, got ${body.event}`);
}
return [{
  json: {
    story_id: storyId,
    session_id: sessionId,
    has_story: !!storyId,
    started_at: new Date().toISOString()
  }
}];

// Compose the briefing markdown.
// Empty story → short hint; otherwise structured brief with title, ruleset,
// top 3 rules (when KB call adds them), acceptance criteria checklist.
const input = $('Validate Input').first().json;
const rpc = $('Fetch Story Context').first().json;
const v = $('Fetch Self-Eval Verdict').first().json;
const verdict = (v && typeof v.score !== 'undefined') ? v : null;
const story = (rpc && rpc.success !== false) ? rpc : null;

let advisory = '';
if (!input.has_story) {
  advisory = '📋 AISHA Dirigent: No active story. Set .aisha/story.json with the current story_id to receive briefings, intent advisories and goal evaluation on Stop.';
} else if (!story) {
  advisory = `📋 AISHA Dirigent: Story ${input.story_id.slice(0,8)} context not retrievable. Briefing skipped this turn; will retry next SessionStart.`;
} else {
  const title = story.title || 'Untitled story';
  const status = story.delivery_status || 'unknown';
  const fp = story.ruleset_fingerprint || story.ruleset?.fingerprint || 'no ruleset';
  const ac = Array.isArray(story.acceptance_criteria) ? story.acceptance_criteria : [];
  const acLines = ac.length ? ac.map(c => `- [ ] ${typeof c === 'string' ? c : (c.text || JSON.stringify(c))}`).join('\n') : '- (no acceptance criteria set)';
  advisory = `📋 **${title}** — status: \`${status}\`\n\n_Ruleset fingerprint:_ \`${fp}\`\n\n**Acceptance criteria**:\n${acLines}`;
}
if (verdict) {
  const fc = Array.isArray(verdict.findings) ? verdict.findings.length : 0;
  advisory += '\n\n_Self-eval:_ ' + (verdict.level || 'n/a') + ' (score ' + (verdict.score != null ? verdict.score : '?') + '/100)' + (fc ? ', ' + fc + ' open finding(s)' : '');
}
return [{
  json: {
    advisory,
    decision: 'allow',
    _audit: { event: 'session_start', story_id: input.story_id, session_id: input.session_id }
  }
}];
